t":"","body":"","imageUrl":""},"form":{"eyebrow":"הרשמה למפגש","title":"שומרים לכם מקום","titleAccent":"","description":"שלושה פרטים, פחות מדקה, ואתם בפנים.","bullets":[],"cardTitle":"להרשמה ללא עלות","cardDescription":"מספר המקומות מוגבל · ההרשמה אינה כרוכה בתשלום · ניתן להסיר בכל עת","buttonText":"להרשמה ללא עלות"},"footer":{"phone":"","email":"","legal":"© המחדש 2026"},"theme":{"primary":"#0B1437","primary2":"#1B2762","accent":"#F5B500","accentLight":"#FFCB3D","purple":"#7C3AED","coral":"#FB7185","dark":"#0A0E27"},"stepChange":{"topbarCta":"להרשמה ללא עלות","brandChip":"בשיתוף","brandChipStrong":"אלטשולר שחם טרייד","heroChips":["מוצ\"ש, 29/8","22:00","75 דקות","בזום","ללא עלות"],"heroCtaNote":"ללא עלות · מספר המקומות מוגבל","typingQuestions":["מה בכלל קורה שם מאחורי הקלעים של השוק?","כמה כסף צריך כדי להתחיל — ומה קורה אם יש לי מעט?","איך מודדים סיכון עוד לפני שקונים?","מה הצעד הראשון שאני עושה מחר בבוקר?"],"trust":[{"value":"20+ שנה","label":"ניסיון בשוק ההון של אבי מלכא"},{"value":"מנכ\"ל","label":"אלטשולר שחם טרייד"},{"value":"10+ שנים","label":"פישל רוזנפלד בליווי כלכלי למשפחות"},{"value":"75 דקות","label":"כולל שו\"ת פתוח בשידור חי"}],"pain":{"eyebrow":"נשמע מוכר?","title":"כל אחד מסביבכם מדבר על השקעות.\nואתם עדיין","titleAccent":"באותו מקום.","dragLabel":"גררו לצדדים","quotes":["\"יש לי קצת כסף בצד, ואני פשוט לא יודע איפה לשים אותו.\"","\"כולם מדברים על מדד אמריקאי כלשהו. אני לא מבין על מה.\"","\"אני נכנס לאתר של הבנק, ויוצא יותר מבולבל ממה שנכנסתי.\"","\"אני מפחד להפסיד דווקא את הכסף שחסכתי בקושי.\"","\"שאלתי חבר, הוא אמר לי לקנות משהו. לא הבנתי מה קניתי.\"","\"אין לי מאה אלף שקל. אז זה בכלל לא בשבילי, נכון?\"","\"כל שנה אני אומר שהשנה אני אלמד את זה. וזהו.\"","\"אני לא רוצה להיכנס למשהו שאני לא מבין לעומק.\"","\"מי שמסביר לי את זה תמיד מנסה למכור לי משהו.\"","\"אני מרגיש שאני מפספס, ואין לי מושג מה בדיוק.\""],"closing":"ההבנה שחסרה לכם נמצאת במרחק 75 דקות.","cta":"להרשמה ללא עלות","ctaNote":"ללא עלות · ניתן לצאת בכל רגע · מקבלים גם את ההקלטה"},"bridge":{"eyebrow":"הנקודה שבה זה משתנה","title":"הכללים של שוק ההון פשוטים ממה שנדמה.\nצריך רק מי שיסביר אותם בגובה העיניים.","body1":"שוק ההון נבנה כדי להיות מקצועי, והמקצועיות הזאת נשמעת מסובכת מבחוץ. מה שמכריע כמעט תמיד זה מי הסביר לכם מה קורה שם, ובאיזו שפה.","body2":"במפגש הזה שני אנשים יסבירו לכם בדיוק את זה. אחד מנהל פלטפורמת מסחר של בית השקעות. השני יושב מול משפחות ומתרגם כסף לשפה של תקציב אמיתי.","punch":"הכללים עצמם, בשפה שלכם."},"agenda":{"eyebrow":"תוכנית המפגש","title":"שישה נושאים. שבעים וחמש דקות. ואפס ידע קודם נדרש.","modules":[{"n":"01","title":"מאיפה מתחילים","promise":"בסוף החלק הזה תדעו בדיוק מה צריך כדי לפתוח חשבון מסחר.","detail":"מה זה חבר בורסה, מה ההבדל מול הבנק, מה נדרש מכם בפועל, וכמה זמן זה באמת לוקח.","tag":""},{"n":"02","title":"השפה של השוק, בעברית","promise":"מניה, אג\"ח, קרן סל, מדד — כל מונח בעברית פשוטה.","detail":"ההסבר במונחים של החיים האמיתיים. אחריו תבינו כל כותרת כלכלית בעיתון.","tag":""},{"n":"03","title":"סיכון: מה זה באמת אומר","promise":"תלמדו איך מודדים סיכון עוד לפני שקונים.","detail":"למה כל השקעה כרוכה בסיכון, מה ההבדל בין תנודתיות להפסד, ומה זה אומר לגבי הכסף של המשפחה שלכם.","tag":""},{"n":"04","title":"כמה כסף מתאים לכם — עם פישל רוזנפלד","promise":"תצאו עם דרך לחשב מה מותר לכם להשקיע, מתוך התקציב שלכם.","detail":"קרן חירום קודם, השקעה אחר כך. איפה עובר הגבול, ואיך יודעים שהגעתם אליו. החלק הכי חשוב למשפחות עם הכנסה בינונית.","tag":"החלק של פישל"},{"n":"05","title":"חמש הטעויות של השנה הראשונה","promise":"תזהו מראש את הטעויות שמתחילים עושים כמעט תמיד.","detail":"מה קורה כשקונים לפי טיפ מחבר, למה תזמון השוק לא עובד, ומה עושים כשהמסך אדום.","tag":""},{"n":"06","title":"מהמסך: איך זה נראה בפועל","promise":"תראו בשידור חי איך נראית פעולה במערכת מסחר.","detail":"אבי מלכא מציג את המסכים עצמם — מה רואים, מה לוחצים, ואיפה אנשים נתקעים.","tag":""}],"qaNote":"+ שו\"ת פתוח בסוף המפגש. אתם שואלים, הם עונים בשידור.","closing":"וזו רק תוכנית הבסיס. את החלק המעניין באמת שואלים המשתתפים.","cta":"להרשמה ללא עלות","ctaNote":"75 דקות · בזום · ללא עלות · ההקלטה נשלחת לכל הנרשמים"},"risk":{"eyebrow":"בואו נדבר על מה שבאמת מטריד","titleAccent":"\"ואם אני אפסיד את הכסף?\"","title":"זו השאלה הנכונה, ויש לה תשובה מלאה.","body1":"כל מי שמבטיח רווח בטוח בשוק ההון — מוכר לכם משהו. השקעה כרוכה בסיכון, ואפשר להפסיד חלק מהכסף או את כולו.","body2":"מה שכן אפשר ללמוד זה איך מסתכלים על הסיכון בעיניים פקוחות: מה ההבדל בין ירידה זמנית להפסד ממומש, וכמה סיכון נכון לכם בשלב הזה.","punch":"זה בדיוק מה שהמפגש עושה. לא מוכר ביטחון — מלמד שיקול דעת.","badHead":"מה לא תשמעו כאן","goodHead":"מה כן תקבלו","rows":[{"bad":"הבטחת תשואה","good":"הסבר איך נמדד סיכון"},{"bad":"\"מניה שחייבים לקנות\"","good":"כלים להחליט לבד"},{"bad":"לחץ לפתוח חשבון היום","good":"זמן לשאול שאלות"}]},"speakersEyebrow":"מי מעביר את המפגש","speakersTitle":"שלושה אנשים, תפקיד אחד: שתבינו.","speakerCards":[{"badge":"20+","meta":"20 שנות ניסיון בשוק ההון","punch":"מנהל את פלטפורמת המסחר, ומסביר איך היא עובדת מבפנים."},{"badge":"15+","meta":"15 שנות ליווי משקי בית","punch":"מחבר בין השקעות לבין התקציב האמיתי של המשפחה."},{"badge":"","meta":"מנחה המפגש","punch":"שואל את השאלות שלכם, ודואג שהשפה תישאר ברורה."}],"audience":{"eyebrow":"אולי אחד מהם זה אתם","title":"המפגש הזה נבנה בשביל אנשים, לא בשביל משקיעים.","cards":[{"quote":"יש לי קרן השתלמות נזילה שלוש שנים ואני לא נוגע בה.","note":"— כי אף אחד לא הסביר מה האפשרויות","dark":false},{"quote":"אני מרוויח בסדר, אבל בסוף החודש לא נשאר כלום להשקיע.","note":"— החלק של פישל נכתב בדיוק בשבילכם","dark":true},{"quote":"פתחתי חשבון מסחר לפני שנה ולא עשיתי בו כלום.","note":"— נראה לכם על המסך איך זה עובד","dark":false},{"quote":"בעלי אומר שנשקיע, ואני חוששת שנפסיד.","note":"— בואו שניכם. תשמעו את שני הצדדים","dark":false}],"footnote":"המפגש בנוי למי שעושה את הצעדים הראשונים שלו בשוק ההון, ורוצה לעשות אותם בעיניים פתוחות."},"proof":{"eyebrow":"למה להקשיב דווקא להם","title":"הסמכות כאן מגיעה מהשטח.","items":[{"value":"20+ שנות ניסיון","label":"אבי מלכא בשוק ההון הישראלי, בבנקאות ובבתי השקעות"},{"value":"בית השקעות מוביל","label":"אלטשולר שחם טרייד — פלטפורמת מסחר עצמאי בשוק ההון בישראל ובארה\"ב"},{"value":"ספר, פודקאסט וקהילה","label":"פישל רוזנפלד מלווה משפחות בכלכלת הבית ומחבר הספר \"פלוס מינוס\""}],"testimonials":"","punch":"כאן יושבים אנשים שעושים את זה כל יום."},"perks":{"eyebrow":"רק למי שנמצא בשידור","title":"החלק שקורה רק","titleAccent":"בשידור החי","body1":"בסוף המפגש נפתח שו\"ת חי. כל אחד שואל את מה שבאמת מפריע לו, ומקבל תשובה ישירה ממי שיושב בצד השני של השוק.","body2":"אלה השאלות שרק אתם יכולים לשאול, כי הן שלכם.","cta":"להרשמה ללא עלות","ctaNote":"ההרשמה ללא עלות · ניתן לבטל בקליק","items":[{"n":"01","title":"ההקלטה המלאה","body":"נשלחת לכל מי שנרשם, גם אם לא הצלחתם להתחבר בזמן.","highlight":false},{"n":"02","title":"מסמך המושגים","body":"כל המונחים מהמפגש בעמוד אחד, בעברית פשוטה. נשלח במייל אחרי.","highlight":false},{"n":"03","title":"הטבה בלעדית למשתתפים","body":"","highlight":true}],"note":"מספר המשתתפים בשידור מוגבל לפי קיבולת הפלטפורמה."},"ctaBand":{"title":"שעה אחת עכשיו.\nושנה שלמה של החלטות טובות יותר.","body":"ההחלטה היחידה שצריך לקבל היום היא להבין על מה מדובר.","cta":"להרשמה ללא עלות","note":"פחות מדקה להרשמה · ללא עלות · ההקלטה נשלחת לכולם"},"register":{"eyebrow":"הרשמה למפגש","title":"שומרים לכם מקום","body":"שלושה פרטים, פחות מדקה, ואתם בפנים.","details":[{"label":"מתי","value":"מוצ\"ש, 29/8, בשעה 22:00"},{"label":"כמה זמן","value":"75 דקות כולל שו\"ת"},{"label":"איפה","value":"בזום — הקישור נשלח במייל ובוואטסאפ"},{"label":"עלות","value":"ללא עלות"}],"legal":"התוכן במפגש הוא כללי ולימודי בלבד ואינו מהווה ייעוץ או שיווק השקעות או תחליף לייעוץ אישי המתחשב בנתוניו וצרכיו של כל אדם. השקעה בשוק ההון כרוכה בסיכון, לרבות אפשרות להפסד חלק מכספי ההשקעה או כולם."},"faqTitle":"מה שעוד לא שאלתם","faq":[{"q":"זה וובינר מכירתי? ינסו למכור לי משהו בסוף?","a":"המפגש הוא לימודי. אין בו חובת רכישה, אין שיחת מכירה שנכפית עליכם ואין לחץ לפתוח חשבון. אתם מקבלים את התוכן המלא בין אם תעשו משהו אחרי ובין אם לא."},{"q":"אני לא יכול להתחבר בשעה הזו. אקבל הקלטה?","a":"כן. ההקלטה של הוובינר נשלחת לכל מי שנרשם, גם אם לא הצלחתם להגיע. השו\"ת החי בסוף המפגש הוא החלק היחיד שלא ייכלל בהקלטה."},{"q":"אין לי הרבה כסף להשקיע. זה עדיין רלוונטי לי?","a":"כן. אחד מששת הנושאים עוסק בדיוק בשאלה כמה כסף מתאים לכם להשקיע ומה לא נכון לגעת בו. המפגש לא מניח סכום מינימלי."},{"q":"אין לי שום רקע בכלכלה. ארגיש שאני לא מבין כלום?","a":"המפגש מתחיל מאפס ידע קודם. כל מונח מקצועי מוסבר בעברית פשוטה, ותפקידו של המנחה לעצור בכל פעם שמשהו נשמע מסובך מדי."},{"q":"איך אני יודע שהפרטים שלי לא יגיעו למפרסמים?","a":"הפרטים משמשים לשליחת הקישור, התזכורת וההקלטה בלבד, ולא מועברים לגורמים שלישיים. אפשר להסיר את עצמכם מהרשימה בכל רגע בקליק אחד."}],"final":{"title":"צעד קטן. שינוי גדול.","titleAccent":"השעה הזאת היא הצעד.","mono":"29/8 במוצ\"ש, 22:00, 75 דקות. בזום. ללא עלות.","cta":"להרשמה ללא עלות","credit":"וובינר \"צעד קטן, שינוי גדול\" · בהנחיית ישראל בוגרד","legal":"התוכן במפגש הוא כללי ולימודי בלבד ואינו מהווה ייעוץ השקעות, שיווק השקעות או תחליף לייעוץ אישי המתחשב בנתוניו ובצרכיו של כל אדם. השקעה בשוק ההון כרוכה בסיכון, לרבות אפשרות להפסד חלק מכספי ההשקעה או כולם. אין בתוצאות העבר כדי להעיד על תוצאות העתיד.","copyright":"© המחדש 2026"},"stickyCta":"להרשמה ללא עלות","stickyNote":"מוצ\"ש 29/8 · 22:00 · ללא עלות","partnerLogoUrl":""},"banner":{"imageUrl":"","linkUrl":"","alt":""},"integrations":{"sendmsg":{"enabled":true,"listName":""}},"styleOverrides":{}}$cfg$,
